// ***************
// Filename: blur_sharpen_top.sv
// Author: FPGA Cores 4 U
// Description: blur_sharpen with its AXI4-Lite register interface, the block
//   designs and testbenches instantiate: the register map blur_sharpen_regs
//   (u_regs, src/include/blur_sharpen_regs.sv, ID "BLSH", VERSION and DATE at
//   0x00-0x08, the registers from 0x10) and the logic blur_sharpen (u_core,
//   src/blur_sharpen.sv), joined by the register interface
//   blur_sharpen_regs_if (u_regs_if). Generated by ip/scripts/regmap_gen.py
//   from blur_sharpen_regs.json and the ports of blur_sharpen: regenerate
//   after changing either. Clock - clk. Reset - synchronous active low rst_n.
// Date: 2026-10-16
module blur_sharpen_top #(
  parameter int N = 5,
  parameter int C = 3,
  parameter int CW = 8,
  parameter int COEF_W = 12,
  parameter int MAX_W = 2048,
  parameter int BORDER = 0,
  parameter int AMOUNT = 1,
  parameter logic [15:0] RESET_W = 16'd1920,
  parameter logic [15:0] RESET_H = 16'd1080
) (
  input  logic clk,
  input  logic rst_n,
  // s_axil: axil_if.slave (ip/shared/src/interfaces/axil_if.sv), ADDR_W = 9
  axil_if.slave s_axil,
  // s_axis: axis_if.slave (ip/shared/src/interfaces/axis_if.sv), DATA_W = C*CW
  axis_if.slave s_axis,
  // m_axis: axis_if.master (ip/shared/src/interfaces/axis_if.sv), DATA_W = C*CW
  axis_if.master m_axis
);
  // register interface between the register map and the logic
  blur_sharpen_regs_if #(.N(N), .COEF_W(COEF_W)) u_regs_if ();

  blur_sharpen_regs #(
    .N(N),
    .COEF_W(COEF_W),
    .RESET_W(RESET_W),
    .RESET_H(RESET_H),
    .K_BLUR(conv2d_pkg::blur_kernel(N)),
    .K_SHARP(conv2d_pkg::sharpen_kernel(N, AMOUNT))
  ) u_regs (
    .clk,
    .rst_n,
    .s_axil(s_axil),
    .r(u_regs_if)
  );
  blur_sharpen #(
    .N(N),
    .C(C),
    .CW(CW),
    .COEF_W(COEF_W),
    .MAX_W(MAX_W),
    .BORDER(BORDER),
    .AMOUNT(AMOUNT),
    .RESET_W(RESET_W),
    .RESET_H(RESET_H)
  ) u_core (
    .clk,
    .rst_n,
    .s_axis,
    .m_axis,
    .regs(u_regs_if)
  );
endmodule
